WITH valid AS (SELECT *, LOWER(device) device_lower FROM sessions WHERE started_at >= DATE '2023-09-17' AND customer_id IS NOT NULL AND device NOT IN ('tablet', 'desktop', 'mobile')), metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) seq_no, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id ASC) event_seq, LAST_VALUE(country, TRUE) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_country FROM valid), with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM metrics), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps), grouped AS (SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, SUM(CASE WHEN device = 'tablet' THEN event_seq ELSE 0 END) AS tablet_event_seq, COUNT(*) AS row_count, SIZE(COLLECT_SET(country)) AS num_countries FROM islands GROUP BY DATE_TRUNC('MONTH', started_at)) SELECT activity_month, tablet_event_seq, num_countries FROM grouped ORDER BY activity_month DESC NULLS FIRST
